470	    ${err ? `<div class="summary-item"><div class="num" style="color:var(--red)">${err}</div>Error</div>` : ''}
471	    <div class="summary-item"><div class="num" style="color:var(--blue)">${totalActive}</div>Active</div>
472	    <div class="summary-item"><div class="num">${totalGpus}</div>GPUs</div>
473	    <div class="summary-item"><div class="num">${healthyAccounts}/${totalAccounts}</div>Pool</div>
474	    <div class="summary-item"><div class="num">$${totalCost.toFixed(0)}</div>Cost</div>
